  const list=a.data||[],o=b.data,cust=U&&PR&&PR.role==='customer';let my={};
  if(cust&&list.length){const {data}=await sb.from('review_votes').select('review_id,vote').in('review_id',list.map(x=>x.id));(data||[]).forEach(v=>my[v.review_id]=v.vote)}
  RV={r:o?o.rating:0,id:o?o.id:null};const s=STS.find(x=>x.id===sid)||{};
  let form;
